/* Sevlink operations: stage changes follow recorded actions, not page visits. */
const stages=[['new','New requests','Review and choose the next action'],['quoting','Quoting','Price remotely from photos and job details'],['assessment','Assessment & quote','A visit is needed before quoting'],['approval','Awaiting client approval','Waiting for agency decisions'],['scheduling','Ready to schedule','Agree the attendance date'],['scheduled','Scheduled visits','Confirm access and attendance'],['underway','Work underway','Visits and repairs in progress'],['invoicing','Ready to invoice','Complete the report and upload invoice'],['closed','Closed jobs','Report and invoice recorded']];
let selectedPod='new',opsSearch='';
const normaliseOps=normalise;normalise=function(){normaliseOps();for(const j of state.jobs){j.opsAction??=null;j.reviewedAt??=null}};
const visibleBeforeOps=visibleJobs;visibleJobs=function(){return role==='sevlink'?state.jobs:visibleBeforeOps()};
function jobStage(j){if(j.status==='Completed')return j.invoices?.length&&j.completedAt&&j.completionNotes?'closed':'invoicing';if(j.status==='In progress')return 'underway';if(j.status==='Scheduled')return 'scheduled';if(j.callout?.status==='Pending'||j.status==='Awaiting approval')return 'approval';if(j.status==='Awaiting schedule'||(j.callout?.status==='Approved'&&!j.schedule&&!['quote','approval'].includes(j.callout.outcome)))return 'scheduling';if(j.opsAction==='quoting')return 'quoting';if(j.opsAction==='assessment')return 'assessment';return j.reviewedAt?'assessment':'new'}
function nextAction(j){return {new:'Review and route request',callouts:'Prepare call-out authorisation',quoting:j.photoRequest?.status==='Requested'?'Waiting for requested photos':'Prepare quote from photos / job details',assessment:'Arrange a visit to assess before quoting',approval:'Await agency decision',scheduling:'Arrange preferred attendance',scheduled:j.access?.status==='Confirmed'?'Attend confirmed visit':'Confirm tenant access',underway:j.callout?'Complete call-out / quote needed':'Record work completion',invoicing:!j.completionNotes?'Complete work report':'Upload invoice',closed:'View completed record'}[jobStage(j)]}
const renderBeforeOps=render;render=function(){renderBeforeOps();if(role==='sevlink'&&['overview','requests'].includes(view))renderOperations()};
function renderOperations(){const list=visibleJobs(),today=new Date(Date.now()+2*3600000).toISOString().slice(0,10),filtered=list.filter(j=>jobStage(j)===selectedPod&&`${j.ref} ${j.title} ${property(j.property)?.name}`.toLowerCase().includes(opsSearch.toLowerCase()));app.innerHTML=heading('Your maintenance control room.','Every request has a place. Every job has a clear next action.')+`<div class="banner">Sevlink operations demo · all agencies shown here. Agency and tenant views remain scoped to their own records. External messages are previews.</div><div class="stats" style="margin-top:22px">${[['New today',list.filter(j=>jobStage(j)==='new'&&j.createdAt?.startsWith(today)).length],['Urgent attention',list.filter(j=>j.priority==='Urgent'&&!['closed','invoicing','cancelled'].includes(jobStage(j))).length],['Visits today',list.filter(j=>j.schedule?.status==='Confirmed'&&j.schedule.when.startsWith(today)&&j.status!=='Completed').length],['Waiting on Sevlink',list.filter(j=>['new','callouts','quoting','assessment','scheduling','underway','invoicing'].includes(jobStage(j))&&j.photoRequest?.status!=='Requested').length]].map(([l,n])=>`<div class="stat"><label>${l}</label><strong>${n.toString().padStart(2,'0')}</strong><small>Live demo workspace</small></div>`).join('')}</div><div class="ops-pods">${stages.map(([key,title,sub])=>`<button class="ops-pod ${selectedPod===key?'selected':''}" onclick="selectPod('${key}')"><span>${title}</span><b>${list.filter(j=>jobStage(j)===key).length}</b><small>${sub}</small></button>`).join('')}</div><div class="panel"><div class="panelhead"><div><h2>${stages.find(s=>s[0]===selectedPod)[1]}</h2><p style="margin:5px 0">${stages.find(s=>s[0]===selectedPod)[2]}</p></div><input id="opsSearch" aria-label="Search this pod" placeholder="Search reference or property…" value="${esc(opsSearch)}"></div><div class="cards">${filtered.map(j=>`<div class="card job-card"><div class="toolbar"><span class="eyebrow">${j.ref}</span>${badge(j.priority)}${j.callout?badge('Call-out'):''}</div><h2>${esc(property(j.property)?.address||property(j.property)?.name)}</h2><p><b>${esc(j.title)}</b><br>${esc(property(j.property)?.name)}<br>${esc(state.agencies.find(a=>a.id===j.agency)?.name)}</p><div class="notice">${j.callout?`<b>Call-out budget: ${money(j.callout.totalBudget)}</b><br>`:''}<b>Next action</b><br>${nextAction(j)}${j.schedule?'<br>'+attendanceTime(j.schedule.when):''}</div><small class="muted">${j.createdAt?'Reported '+date(j.createdAt)+' · '+waitingTime(j.reviewedAt||j.createdAt):'Earlier demo request · time not recorded'}${j.reviewedAt?'<br>Reviewed '+date(j.reviewedAt):''}</small><div class="actions"><button class="primary" onclick="jobDetail('${j.id}','${['scheduled','scheduling'].includes(selectedPod)?'schedule':selectedPod==='invoicing'?'invoices':'comments'}')">Open job →</button></div></div>`).join('')||'<div class="empty">No jobs in this pod. Requests move here when the relevant action is recorded.</div>'}</div></div>`;$('#opsSearch').oninput=e=>{opsSearch=e.target.value;const start=e.target.selectionStart;renderOperations();$('#opsSearch').focus();$('#opsSearch').setSelectionRange(start,start)}}
function selectPod(pod){selectedPod=pod==='callouts'?'scheduling':pod;opsSearch='';renderOperations()}
const detailBeforeOps=jobDetail;jobDetail=function(jid,section='comments'){detailBeforeOps(jid,section);const j=getJob(jid);if(!j)return;const calloutHtml=calloutBudgetPanel(j);$('#jobcontent').insertAdjacentHTML('afterbegin',calloutHtml);if(role==='sevlink'){let html='';if(jobStage(j)==='new')html+=`<button class="primary" onclick="routeQuoting('${j.id}')">Quote remotely</button><button class="secondary" onclick="routeAssessment('${j.id}')">Assessment & quote — visit needed</button>`;if(jobStage(j)==='quoting')html+=`<button class="primary" onclick="quoteForm('${j.id}')">Prepare remote quote</button><button class="secondary" onclick="requestPhotosForm('${j.id}')">Request photos</button><button class="secondary" onclick="routeAssessment('${j.id}')">A visit is needed</button>`;if(jobStage(j)==='assessment')html+=`<button class="primary" onclick="bookingForm('', '${j.id}')">Arrange assessment attendance</button><button class="secondary" onclick="routeQuoting('${j.id}')">Use photos instead</button>`;if(j.status==='Scheduled')html+=`<button class="primary" onclick="recordAttendance('${j.id}')">Mark appointment attended</button>`;if(j.status==='In progress'&&j.callout)html+=`<button class="primary" onclick="findingsForm('${j.id}')">Complete call-out / quote needed</button>`;if(j.status==='Completed'&&!j.completionNotes)html+=`<button class="secondary" onclick="completeEarlierReport('${j.id}')">Complete work report</button>`;if(j.status==='Completed')html+=`<button class="secondary" onclick="invoiceForm('${j.id}')">Upload invoice</button>`;$('#jobcontent').insertAdjacentHTML('beforeend',`<div class="actions">${html}</div><div class="notice">Operations stage: <b>${stages.find(s=>s[0]===jobStage(j))[1]}</b><br>${nextAction(j)}</div>`)}if(j.callout&&!j.callout.repairAuthorised&&!approvedBeforeOps(j)){const b=$('#complete');if(b)b.remove()}};
async function routeAssessment(jid){const j=getJob(jid);if(!j||role!=='sevlink'||!['new','quoting'].includes(jobStage(j)))return;if(await commit(()=>{j.reviewedAt=now();j.opsAction='assessment';j.assigned=true;j.team='Sevlink Repairs Team';addEvent(j,'Request reviewed','A site visit is required to assess the issue before quoting.')})){render();jobDetail(jid);toast('Moved to Assessment & quote — visit needed.')}}
function calloutForm(jid){const j=getJob(jid);if(!j||role!=='sevlink'||!['new','callouts','assessment'].includes(jobStage(j)))return;openForm('Arrange a call-out.',`<p>Attendance and investigation can be authorised before a repair quote exists. Urgency alone does not authorise a charge.</p><label>Call-out attendance / investigation fee (ZAR)</label><input name="fee" type="number" min="0" max="100000" step="0.01" required value="${j.callout?.fee??''}"><label>Requested additional repair budget (excluding the call-out fee)</label><input name="budget" type="number" min="0" max="1000000" step="0.01" required value="${j.callout?.budget??0}"><label>What the call-out covers</label><textarea name="scope" required maxlength="1500" rows="3">${esc(j.callout?.scope||'Attend, investigate and report findings. Any repair outside the authorised budget requires further approval.')}</textarea>`,'Request client authorisation',async d=>{if(await requestCallout(jid,Number(d.get('fee')),Number(d.get('budget')),d.get('scope'))){render();jobDetail(jid);toast('Moved to Awaiting client approval.')}})}
async function requestCallout(jid,fee,budget,scope){const j=getJob(jid);if(!j||role!=='sevlink'||!['new','callouts','assessment'].includes(jobStage(j))||!Number.isFinite(fee)||fee<0||!Number.isFinite(budget)||budget<0)return false;return commit(()=>{j.callout={fee,budget,scope,status:'Pending',findings:'',repairAuthorised:false};j.opsAction='callout';j.reviewedAt??=now();j.assigned=true;j.team='Sevlink Repairs Team';j.status='Awaiting approval';addEvent(j,'Call-out authorisation requested','Attendance fee '+money(fee)+'; additional repair budget '+money(budget),'financial');notify(j,'Call-out authorisation',j.ref+': call-out fee and repair budget need approval.')})}
function authoriseCallout(jid){const j=getJob(jid);if(!j||role!=='manager'||j.callout?.status!=='Pending')return;openForm('Authorise the call-out.',`<p>${esc(j.callout.scope)}</p><div class="notice">Call-out fee: <b>${money(j.callout.fee)}</b><br>This approves attendance and investigation. A separate repair budget is optional.</div><label>Maximum additional repair spend authorised (ZAR)</label><input name="budget" type="number" min="0" max="1000000" step="0.01" required value="${j.callout.budget}"><label style="display:flex;gap:10px;align-items:center"><input style="width:auto" type="checkbox" required>I approve the disclosed attendance fee and the repair limit above.</label>`,'Authorise attendance',async d=>{if(await approveCallout(jid,Number(d.get('budget')))){render();jobDetail(jid,'schedule');toast('Call-out authorised. Ready to schedule.')}})}
async function approveCallout(jid,budget){const j=getJob(jid);if(!j||role!=='manager'||j.callout?.status!=='Pending'||!Number.isFinite(budget)||budget<0)return false;return commit(()=>{j.callout.budget=budget;j.callout.status='Approved';j.callout.approvedAt=now();j.status='Awaiting schedule';j.schedule=null;addEvent(j,'Call-out authorised','Attendance '+money(j.callout.fee)+'; maximum additional repairs '+money(budget),'financial');notify(j,'Call-out approved',j.ref+': attendance authorised; suggest a preferred time.')})}
const approvedBeforeOps=approved;approved=function(j){return approvedBeforeOps(j)||(j.callout?.status==='Approved'&&!['quote','approval'].includes(j.callout.outcome))};
async function recordAttendance(jid){const j=getJob(jid);if(!j||role!=='sevlink'||j.status!=='Scheduled')return;if(await commit(()=>{j.status='In progress';j.opsAction='attending';addEvent(j,'Attendance recorded','Sevlink recorded attendance for investigation / work.')})){render();jobDetail(jid);toast('Moved to Work underway.')}}
function findingsForm(jid){const j=getJob(jid);if(!j||role!=='sevlink'||j.status!=='In progress'||!j.callout)return;openForm('Call-out findings.',`<label>Findings and diagnosis</label><textarea name="findings" required maxlength="2000" rows="4"></textarea><label>Findings photo (optional)</label><input name="photo" type="file" accept="image/jpeg,image/png,image/webp"><label>Next step</label><select name="outcome"><option value="resolved">Resolved / repair within authorised budget</option><option value="approval">Request approval for a repair cost</option><option value="quote">Further work requires a formal quote</option></select><label>Additional repair cost if resolved (excluding call-out fee)</label><input name="actual" type="number" min="0" max="1000000" step="0.01" value="0"><div class="notice">Attendance fee: ${money(j.callout.fee)}<br>Maximum additional spend authorised: ${money(j.callout.budget)}<br>Work above that limit needs client approval.</div>`,'Save findings & next step',async d=>{let photo;try{photo=await fileData(d.get('photo'),imageTypes)}catch(e){toast(e.message);return}const outcome=d.get('outcome');if(await saveFindings(jid,d.get('findings'),outcome,Number(d.get('actual')),photo)){render();if(outcome==='resolved')completionForm(jid);else if(outcome==='approval')repairApprovalForm(jid);else quoteForm(jid)}})}
async function saveFindings(jid,findings,outcome,actual,photo){const j=getJob(jid);if(!j||role!=='sevlink'||j.status!=='In progress'||!j.callout||!['resolved','approval','quote'].includes(outcome))return false;if(outcome==='resolved'&&(!Number.isFinite(actual)||actual<0||actual>j.callout.budget)){toast('Repair cost exceeds the approved budget. Request approval or submit a quote first.');return false}return commit(()=>{j.callout.findings=findings;j.callout.outcome=outcome;j.callout.actual=outcome==='resolved'?actual:null;j.callout.repairAuthorised=outcome==='resolved';if(photo){photo.phase='before';photo.at=now();j.photos.push(photo);j.beforePhotos.push(photo)}addEvent(j,'Call-out findings',findings);if(outcome!=='resolved'){j.opsAction='quoting';j.status='New';j.previousVisit=j.schedule;j.schedule=null;addEvent(j,'Further work required',outcome==='quote'?'Prepare a formal repair quote.':'Request client approval for the repair scope and cost.')}else addEvent(j,'Repair within authorised limit','Additional repair cost '+money(actual),'financial')})}
function repairApprovalForm(jid){const j=getJob(jid);if(!j||role!=='sevlink'||!['quoting','assessment','underway'].includes(jobStage(j)))return;openForm('Request repair approval.',`<label>Work proposed</label><textarea name="scope" required rows="4" maxlength="2000"></textarea><label>Proposed repair total (ZAR)</label><input name="amount" type="number" min="0.01" max="10000000" step="0.01" required><div class="notice">A document is optional for this cost approval. The scope and price are saved on the job for the client to approve.</div>`,'Submit repair cost for approval',async d=>{if(await requestRepairCost(jid,Number(d.get('amount')),d.get('scope'))){render();jobDetail(jid,'quotes');toast('Moved to Awaiting client approval.')}})}
async function requestRepairCost(jid,amount,scope){const j=getJob(jid);if(!j||role!=='sevlink'||!['quoting','assessment','underway'].includes(jobStage(j))||!Number.isFinite(amount)||amount<=0)return false;return commit(()=>{j.quotes.push({id:id('q'),supplier:'Sevlink — repair cost approval',amount,scope,file:null,status:'Pending',kind:'cost approval',at:now()});j.status='Awaiting approval';if(j.callout)j.callout.outcome='approval';j.previousVisit=j.schedule||j.previousVisit;j.schedule=null})}
const completeBeforeOps=completionForm;completionForm=function(jid){const j=getJob(jid);if(j?.callout&&!j.callout.repairAuthorised&&!approvedBeforeOps(j)){toast('Record findings and confirm repair authorisation before completion.');return}return completeBeforeOps(jid)};
function completeEarlierReport(jid){const j=getJob(jid);if(!j||role!=='sevlink'||j.status!=='Completed')return;openForm('Complete the work report.',`<label>Work carried out</label><textarea name="notes" required rows="4" maxlength="2000"></textarea><label>Checks completed</label><textarea name="checks" required rows="3" maxlength="1000"></textarea>`,'Save work report',async d=>{if(await commit(()=>{j.completionNotes=d.get('notes');j.completionChecks=d.get('checks');j.completedAt??=now();addEvent(j,'Completion report updated',j.completionNotes)})){render();jobDetail(jid,'report')}})}

function waitingTime(at){const minutes=Math.max(0,Math.floor((Date.now()-Date.parse(at))/60000));return minutes<60?minutes+' min since last review':minutes<1440?Math.floor(minutes/60)+' hr since last review':Math.floor(minutes/1440)+' days since last review'}
async function routeCallout(jid){const j=getJob(jid);if(!j||role!=='sevlink'||jobStage(j)!=='new')return;if(await commit(()=>{j.reviewedAt=now();j.opsAction='callout';j.assigned=true;j.team='Sevlink Repairs Team';addEvent(j,'Call-out route selected','Sevlink is preparing attendance authorisation.')})){render();jobDetail(jid);toast('Moved to Call-outs.')}}
